 * Writes out the members of a union or an intersection.
 *
 * A member that is itself a compound type is parenthesised, which is how PHP
 * writes the one case where that happens: an intersection inside a union.
 *
 * @param IntersectionType|UnionType $type The compound type to write out
 *
 * @return list<string> The members as written, in source order
 */
public static function parts(IntersectionType|UnionType $type): array
{
    $written = [];
    foreach ($type->types as $member) {
        $text = self::of($member) ?? '';
        $written[] = $member instanceof ComplexType && !$member instanceof NullableType
            ? '('.$text.')'
            : $text;
    }

    return $written;
}

