25	 *
26	 * `to_json_string` is the one that matters most for the reader peq is built for. An
27	 * agent that has matched a pattern and wants the whole of what it found — labels,
28	 * properties and all — asks for it as JSON in one column rather than enumerating
29	 * properties it would have to know the names of first.
30	 *
31	 * @visibility App\Gql
32	 */
33	final class GeneralFunctions
34	{
35	    /**
36	     * Returns the first value that is there.
37	     *
38	     * @param list<Datum> $values The values, in the order they are preferred
39	     *
40	     * @example The first value that is there is the answer
41	     *     $values = [new \App\Gql\Datum\NullDatum(), new \App\Gql\Datum\StringDatum('Unknown')];
42	     *     \App\Gql\Invocation\GeneralFunctions::coalesce($values)->toText() // => 'Unknown'
43	     * @example When none of them is there, neither is the answer
44	     *     \App\Gql\Invocation\GeneralFunctions::coalesce([new \App\Gql\Datum\NullDatum()])->kind() // => \App\Gql\Datum\DatumKind::Null
45	     *
46	     * @return Datum The first value that is there, or the absence of one
47	     */
48	    public static function coalesce(array $values): Datum
49	    {
50	        foreach ($values as $value) {
51	            if ($value->kind() !== DatumKind::Null) {
52	                return $value;
53	            }
54	        }
55	
56	        return new NullDatum();
57	    }
