15	use App\Gql\GqlException;
16	use App\Gql\StatusCode;
17	
18	/**
19	 * The functions GQL offers that belong to no one kind of value.
20	 *
21	 * `coalesce` and `nullif` are the two moves a query makes around absent values: the
22	 * first supplies one, the second withdraws one. Between them they are how a reader
23	 * escapes three-valued logic without writing a `CASE`.
24	 *
25	 * `to_json_string` is the one that matters most for the reader peq is built for. An
26	 * agent that has matched a pattern and wants the whole of what it found — labels,
27	 * properties and all — asks for it as JSON in one column rather than enumerating
28	 * properties it would have to know the names of first.
29	 *
30	 * @visibility App\Gql
31	 */
32	final class GeneralFunctions
33	{
34	    /**
35	     * Returns the first value that is there.
36	     *
37	     * @param list<Datum> $values The values, in the order they are preferred
38	     *
39	     * @example The first value that is there is the answer
40	     *     $values = [new \App\Gql\Datum\NullDatum(), new \App\Gql\Datum\StringDatum('Unknown')];
41	     *     \App\Gql\Invocation\GeneralFunctions::coalesce($values)->toText() // => 'Unknown'
42	     * @example When none of them is there, neither is the answer
43	     *     \App\Gql\Invocation\GeneralFunctions::coalesce([new \App\Gql\Datum\NullDatum()])->kind() // => \App\Gql\Datum\DatumKind::Null
44	     *
45	     * @return Datum The first value that is there, or the absence of one
46	     */
47	    public static function coalesce(array $values): Datum
48	    {
49	        foreach ($values as $value) {
50	            if ($value->kind() !== DatumKind::Null) {
51	                return $value;
52	            }
53	        }
54	
55	        return new NullDatum();
56	    }
57	
58	    /**
59	     * Returns a value, unless it equals another, in which case nothing.
60	     *
61	     * This is how a query turns a stand-in value back into an absent one: a
62	     * visibility recorded as `unknown`, a file path recorded as an empty string.
63	     *
64	     * @param Datum $value    The value
65	     * @param Datum $withdraw What it must not equal
66	     *
67	     * @example A value that equals the one withdrawn becomes absent
68	     *     $value = new \App\Gql\Datum\StringDatum('unknown');
69	     *     \App\Gql\Invocation\GeneralFunctions::nullif($value, new \App\Gql\Datum\StringDatum('unknown'))->kind() // => \App\Gql\Datum\DatumKind::Null
70	     * @example Any other value is itself
71	     *     $value = new \App\Gql\Datum\StringDatum('public');
72	     *     \App\Gql\Invocation\GeneralFunctions::nullif($value, new \App\Gql\Datum\StringDatum('unknown'))->toText() // => 'public'
73	     *
74	     * @return Datum The value, or the absence of one
75	     */
76	    public static function nullif(Datum $value, Datum $withdraw): Datum
77	    {
78	        return DatumOrder::equals($value, $withdraw) === true ? new NullDatum() : $value;
79	    }
80	
81	    /**
82	     * Returns a value written as JSON.
83	     *
84	     * @param Datum $value The value
85	     *
86	     * @example A symbol serialises as everything a query could have selected it by
87	     *     $node = new \App\Gql\Datum\NodeDatum('App\\Invoice', ['Class'], []);
88	     *     \App\Gql\Invocation\GeneralFunctions::toJsonString($node)->toText() // => '{"id":"App\\\\Invoice","labels":["Class"],"properties":{}}'
89	     *
90	     * @return Datum The JSON, as a string
91	     */
92	    public static function toJsonString(Datum $value): Datum
93	    {
94	        return new StringDatum(DatumJson::of($value));
95	    }
96	
97	    /**
98	     * Returns a moment in time: the one written, or the one it is now.
99	     *
100	     * @param list<Datum> $values The moment as written, or nothing to mean now
101	     *
102	     * @example A moment written in ISO 8601 is read as that moment
103	     *     $written = [new \App\Gql\Datum\StringDatum('2024-01-15T10:30:00+00:00')];
104	     *     \App\Gql\Invocation\GeneralFunctions::zonedDatetime($written)->toText() // => '2024-01-15T10:30:00+00:00'
105	     * @example Something that is not a moment is reported rather than guessed at
106	     *     \App\Gql\Invocation\GeneralFunctions::zonedDatetime([new \App\Gql\Datum\StringDatum('yesterday-ish')]) // throws \App\Gql\GqlException: invalid value type
107	     *
108	     * @return Datum The moment
109	     *
110	     * @throws GqlException If what is written is not a moment
111	     */
112	    public static function zonedDatetime(array $values): Datum
113	    {
114	        if ($values !== [] && $values[0]->kind() === DatumKind::Null) {
115	            return new NullDatum();
116	        }
117	
118	        $written = $values === [] ? 'now' : TextOperation::characters($values[0]);
119	        $moment = date_create_immutable($written);
120	        if ($moment === false) {
121	            throw GqlException::because(StatusCode::InvalidType, sprintf('"%s" is not a moment in time', $written));
122	        }
123	
124	        return new DateTimeDatum($moment);
125	    }
