19	/**
20	 * GQL's functions over the graph itself.
21	 *
22	 * These take apart what a pattern bound. A path is the most useful thing a query
23	 * about code can return — not "these two symbols are connected" but "here is the
24	 * chain between them" — and these are how a reader gets at its parts: the symbols it
25	 * passes through, the relations it crosses, how long it is.
26	 *
27	 * `labels` completes the picture from the other direction. A pattern selects by
28	 * label; `labels` is how a result says which ones a symbol actually turned out to
29	 * carry, which is what an agent needs in order to ask a better question next.
30	 *
31	 * @visibility App\Gql
32	 */
33	final class GraphFunctions
34	{
35	    /**
36	     * Returns the symbols a path passes through, in order.
37	     *
38	     * @param Datum $value The path
39	     *
40	     * @example A path of one relation passes through two symbols
41	     *     $path = \App\Gql\Datum\PathDatum::at(new \App\Gql\Datum\NodeDatum('a'))
42	     *         ->continuedBy(new \App\Gql\Datum\EdgeDatum('e', [], [], 'a', 'b'), new \App\Gql\Datum\NodeDatum('b'));
43	     *     \App\Gql\Invocation\GraphFunctions::nodes($path)->toText() // => '[a, b]'
44	     *
45	     * @return Datum The symbols, or the absence of them
46	     *
47	     * @throws GqlException If the value is not a path
48	     */
