18	/**
19	 * Running a RETURN: deciding what the reader is shown.
20	 *
21	 * The one real decision here is whether the projection summarises its rows or reports
22	 * them, and it is made from the shape of the expressions rather than from the data:
23	 * a projection holding a summary anywhere inside it produces one row per group, and
24	 * one holding none produces one row per row. Grouping without a `GROUP BY` makes a
25	 * single group of everything, which is why `RETURN count(*)` answers once.
26	 *
27	 * Projected columns are added to the row they came from rather than replacing it.
28	 * That is what lets an ordering written after the projection sort by something the
29	 * projection did not show — `RETURN a, b ORDER BY r.creationDate` — which GQL allows
30	 * and a reader reaches for more often than it sounds.
31	 *
32	 * @visibility App\Gql
33	 */
34	final class ReturnExecution
35	{
36	    /**
37	     * @param RowExecution $rows How rows are ordered and paged
38	     */
39	    public function __construct(
40	        private readonly RowExecution $rows,
41	    ) {}
42	
43	    /**
44	     * Returns what the columns of the result are called.
45	     *
46	     * A projection that asks for everything is headed by the names that are in scope
47	     * where it is written, which is decided when the query runs rather than when it
48	     * is read.
49	     *
50	     * @param ReturnClause $clause The clause
51	     * @param BindingTable $table  The rows it is given
52	     *
53	     * @example A projection that asks for everything shows what is bound
54	     *     $row = \App\Gql\Binding\BindingRow::unit()->with('p', new \App\Gql\Datum\NullDatum());
55	     *     $execution = new \App\Gql\Execution\ReturnExecution(new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation()));
56	     *     $execution->headings(new \App\Gql\Syntax\Clause\ReturnClause(), new \App\Gql\Binding\BindingTable([$row])) // => ['p']
57	     *
58	     * @return list<string> The headings, in the order they are shown
59	     */
60	    public function headings(ReturnClause $clause, BindingTable $table): array
61	    {
62	        if ($clause->everything()) {
63	            return $table->names();
64	        }
65	
66	        return array_map(static fn (Projection $column): string => $column->heading(), $clause->columns);
67	    }
68	
69	    /**
70	     * Returns the rows a RETURN produces.
71	     *
72	     * @param ReturnClause $clause The clause
73	     * @param BindingTable $table  The rows it is given
74	     *
75	     * @example A projection that summarises answers once, even over no rows at all
76	     *     $counted = new \App\Gql\Syntax\Expression\CallExpression('count', [], false, true);
77	     *     $clause = new \App\Gql\Syntax\Clause\ReturnClause([new \App\Gql\Syntax\Clause\Projection($counted, 'n', 'count(*)')]);
78	     *     $execution = new \App\Gql\Execution\ReturnExecution(new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation()));
79	     *     $execution->run($clause, \App\Gql\Binding\BindingTable::nothing())->rows[0]->value('n')->toText() // => '0'
80	     *
81	     * @return BindingTable The rows it produces
82	     *
83	     * @throws GqlException If a column cannot be worked out
84	     */
85	    public function run(ReturnClause $clause, BindingTable $table): BindingTable
86	    {
87	        $produced = $this->summarises($clause)
88	            ? $this->summarised($clause, $table)
89	            : $this->reported($clause, $table);
90	
91	        if ($clause->distinct) {
92	            $produced = self::once($this->headings($clause, $table), $produced);
93	        }
94	        if ($clause->orderBy !== []) {
95	            $produced = $this->rows->sorted($clause->orderBy, $produced);
96	        }
97	        if ($clause->page !== null) {
98	            $produced = array_slice($produced, $clause->page->offset, $clause->page->limit);
99	        }
100	
101	        return new BindingTable($produced);
102	    }
103	
104	    /**
105	     * Reports whether a projection summarises its rows rather than reporting them.
106	     *
107	     * @param ReturnClause $clause The clause
108	     *
109	     * @example A projection that groups summarises
110	     *     $key = new \App\Gql\Syntax\Expression\VariableExpression('kind');
