14	/**
15	 * Writes the paths a query bound as one tree.
16	 *
17	 * Paths are how a query answers "how does this reach that", and a list of them
18	 * repeats their shared beginnings once per path — which, for a controller that
19	 * reaches forty things through the same two calls, is most of the answer. Drawing
20	 * them as a tree writes each shared beginning once, which is the same reason peq's
21	 * own inspection draws a tree.
22	 *
23	 * The difference is what decides the shape. The inspection walks whatever the graph
24	 * holds; this draws whatever the query chose to bind, so the tree is of the reader's
25	 * own question rather than of the whole graph.
26	 *
27	 * A query that binds no path writes nothing here, and its answer is a table. Binding
28	 * one is a deliberate act — `MATCH p = (a)-[:call]->{1,4}(b)` — and a reader who did
29	 * not do it did not ask for a tree.
30	 *
31	 * @visibility App\Reporter
32	 */
33	final class TreeWriter implements QueryReporter
34	{
35	    /**
36	     * Writes the paths the answer holds as a tree.
37	     *
38	     * @param ResultTable     $result What the query answered
39	     * @param OutputInterface $output Where it is written
40	     */
41	    #[Override]
42	    public function report(ResultTable $result, OutputInterface $output): void
43	    {
44	        $paths = self::paths($result);
45	        if ($paths === []) {
46	            return;
47	        }
48	
49	        $previous = [];
50	        $continues = [];
51	        foreach ($paths as $place => $path) {
52	            $shared = self::sharedLength($previous, $path);
53	            for ($depth = $shared; $depth < count($path); ++$depth) {
54	                $continues[$depth] = self::hasSibling($paths, $place, $depth);
55	                $output->writeln(self::line($path, $depth, $continues), OutputInterface::OUTPUT_RAW);
56	            }
57	            $previous = $path;
58	        }
59	    }
60	
61	    /**
62	     * Returns the paths an answer holds, in the order a tree draws them.
63	     *
64	     * They are sorted so that paths sharing a beginning stand together, which is what
65	     * lets the tree be drawn in one pass without building one.
66	     *
67	     * @param ResultTable $result What the query answered
68	     *
69	     * @example An answer that binds no path holds no paths
70	     *     \App\Reporter\Query\TreeWriter::paths(\App\Gql\Result\ResultTable::nothing()) // => []
71	     *
72	     * @return list<list<TreeStep>> The paths, sorted and without repetition
73	     */
74	    public static function paths(ResultTable $result): array
75	    {
76	        $found = [];
77	        foreach ($result->rows as $row) {
78	            foreach (ResultElements::flattened($row->values) as $value) {
79	                if ($value instanceof PathDatum) {
80	                    $steps = self::steps($value);
81	                    $found[self::signature($steps)] = $steps;
82	                }
83	            }
84	        }
85	        ksort($found);
86	
87	        return array_values($found);
88	    }
89	
90	    /**
91	     * Returns one path as the steps a tree draws it in.
92	     *
93	     * @param PathDatum $path The path
94	     *
95	     * @example A path that crosses nothing is one step
96	     *     count(\App\Reporter\Query\TreeWriter::steps(\App\Gql\Datum\PathDatum::at(new \App\Gql\Datum\NodeDatum('a')))) // => 1
97	     * @example A path that crosses one relation is two
98	     *     $path = \App\Gql\Datum\PathDatum::at(new \App\Gql\Datum\NodeDatum('a'))
99	     *         ->continuedBy(new \App\Gql\Datum\EdgeDatum('e', ['calls'], [], 'a', 'b'), new \App\Gql\Datum\NodeDatum('b'));
