3	declare(strict_types=1);
4	
5	namespace App\Gql\Element;
6	
7	use App\Analyzer\Graph\Edge;
8	use App\Analyzer\Graph\Graph;
9	use App\Analyzer\Graph\Node;
10	use App\Gql\Datum\EdgeDatum;
11	use App\Gql\Datum\NodeDatum;
12	
13	/**
14	 * Turns the graph peq analysed into the graph a query can be written against.
15	 *
16	 * The two are the same graph seen from different sides. peq's own is built for
17	 * walking away from a symbol and back towards it; a query's is built for matching
18	 * patterns, which means labels to select by, properties to compare, and adjacency in
19	 * both directions.
20	 *
21	 * Doing the turning once, up front, is deliberate. A query may match a pattern
22	 * against every symbol in a codebase, and working out a symbol's labels each time it
23	 * is considered would make the cost of a pattern depend on how often it fails.
24	 *
25	 * @visibility App
26	 */
27	final class GraphProjection
28	{
29	    /**
30	     * Returns the analysed graph as a query sees it.
31	     *
32	     * @param Graph $graph The graph analysis produced
33	     *
34	     * @example Every analysed symbol becomes a symbol a pattern can match
35	     *     $graph = new \App\Analyzer\Graph\Graph();
36	     *     $graph->addNode(new \App\Analyzer\Graph\Node\ClassNode(\App\Analyzer\Graph\NodeId\ClassNodeId::of('App\\Invoice'), true));
37	     *     count(\App\Gql\Element\GraphProjection::of($graph)->nodes()) // => 1
38	     * @example A relation is reachable from both of its ends
39	     *     $graph = new \App\Analyzer\Graph\Graph();
40	     *     $meta = new \App\Analyzer\Graph\FileMeta('/project/src/Invoice.php', 12, 1);
41	     *     $caller = new \App\Analyzer\Graph\Node\MethodNode(\App\Analyzer\Graph\NodeId\MethodNodeId::of('App\\Invoice', 'total'), true);
42	     *     $called = new \App\Analyzer\Graph\Node\MethodNode(\App\Analyzer\Graph\NodeId\MethodNodeId::of('App\\Money', 'add'), true);
43	     *     $graph->addEdge(new \App\Analyzer\Graph\Edge\Usage\MethodCallEdge($caller, $called, $meta));
44	     *     count(\App\Gql\Element\GraphProjection::of($graph)->arriving('App\\Money::add')) // => 1
45	     *
46	     * @return ElementGraph The graph a query is written against
47	     */
48	    public static function of(Graph $graph): ElementGraph
49	    {
50	        $nodes = [];
51	        foreach ($graph->nodes() as $node) {
52	            $nodes[$node->id()->toString()] = self::node($node);
53	        }
54	
55	        $leaving = [];
56	        $arriving = [];
57	        foreach ($graph->authoredEdges() as $edge) {
58	            $datum = self::edge($edge);
59	            $leaving[$datum->origin][] = $datum;
60	            $arriving[$datum->target][] = $datum;
61	        }
62	
63	        return new ElementGraph($nodes, $leaving, $arriving);
64	    }
65	
66	    /**
67	     * Returns one symbol as a query sees it.
68	     *
69	     * @param Node $node The analysed symbol
70	     *
71	     * @example A symbol carries the labels a pattern selects it by
72	     *     $named = \App\Analyzer\Graph\NodeId\ClassNodeId::of('App\\Invoice');
73	     *     \App\Gql\Element\GraphProjection::node(new \App\Analyzer\Graph\Node\ClassNode($named, true))->labels // => ['Class', 'ClassLike', 'Resolved']
74	     *
75	     * @return NodeDatum The symbol
76	     */
77	    public static function node(Node $node): NodeDatum
78	    {
79	        return new NodeDatum(
80	            $node->id()->toString(),
81	            NodeLabels::of($node),
82	            NodeProperties::of($node),
83	        );
84	    }
85	
86	    /**
87	     * Returns one relation as a query sees it.
88	     *
89	     * A relation is identified by its two ends and its kind, which is exactly what
90	     * makes two relations the same one in the analysed graph. That keeps a path mode
91	     * that forbids crossing an edge twice forbidding the right thing.
92	     *
93	     * @param Edge $edge The analysed relation
94	     *
95	     * @example A relation is identified by what it joins and how
96	     *     $meta = new \App\Analyzer\Graph\FileMeta('/project/src/Invoice.php', 12, 1);
97	     *     $caller = new \App\Analyzer\Graph\Node\MethodNode(\App\Analyzer\Graph\NodeId\MethodNodeId::of('App\\Invoice', 'total'), true);
98	     *     $called = new \App\Analyzer\Graph\Node\MethodNode(\App\Analyzer\Graph\NodeId\MethodNodeId::of('App\\Money', 'add'), true);
99	     *     $written = new \App\Analyzer\Graph\Edge\Usage\MethodCallEdge($caller, $called, $meta);
100	     *     \App\Gql\Element\GraphProjection::edge($written)->id // => 'App\\Invoice::total|method-call|App\\Money::add'
101	     *
102	     * @return EdgeDatum The relation
103	     */
104	    public static function edge(Edge $edge): EdgeDatum
105	    {
106	        $origin = $edge->from()->toString();
107	        $target = $edge->to()->toString();
108	
109	        return new EdgeDatum(
110	            $origin.'|'.$edge->kind()->value.'|'.$target,
111	            EdgeLabels::of($edge->kind()),
112	            EdgeProperties::of($edge),
113	            $origin,
114	            $target,
115	        );
116	    }
117	}

